    /// Clicking the Explorer header's "Collapse All" toolbar button must
    /// collapse every expanded directory except the workspace root (#1693)
    /// — asserted on painted content (a deeply nested file's row vanishes
    /// from the screen), not on `explorer_expanded`'s size alone, per
    /// `CLAUDE.md`'s "assert on rendered output" testing rule.
    #[test]
    fn clicking_explorer_collapse_all_collapses_nested_directories_but_keeps_the_root_open() {
        let dir = std::env::temp_dir().join(format!(
            "vimcode_test_1693_collapse_all_{}_{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        let nested = dir.join("sub").join("deeper");
        std::fs::create_dir_all(&nested).unwrap();
        let deep_file = nested.join("deepfile.txt");
        std::fs::write(&deep_file, "marker\n").unwrap();

        let mut engine = Engine::new();
        engine.settings.use_nerd_fonts = Some(false);
        engine.cwd = dir.clone();
        engine
            .app_shell
            .show_panel(&quadraui::WidgetId::new(PANEL_EXPLORER));
        engine.explorer_reveal_path(&deep_file);
        let mut h = harness(engine, 1400, 900);
        h.driver.render();

        assert!(
            h.driver.screen_contains("deepfile.txt"),
            "precondition: revealing the deep file must expand every \
             ancestor so its row is actually painted; painted texts: {:?}",
            h.driver.painted_texts()
        );

        // `explorer_toolbar_status_bar` pads every fallback glyph with a
        // leading/trailing space (`" c "`), so searching for that padded
        // form (rather than a bare `"c"`) can't accidentally match a `c`
        // inside a painted file/directory name.
        let (x, y) = h.driver.find(" c ").unwrap_or_else(|| {
            panic!(
                "could not find Collapse All's \" c \" fallback glyph; \
                 painted texts: {:?}",
                h.driver.painted_texts()
            )
        });

        h.driver.click(x, y);

        let _ = std::fs::remove_dir_all(&dir);

        assert!(
            !h.driver.screen_contains("deepfile.txt"),
            "Collapse All must collapse the nested directories so the deep \
             file's row is no longer painted; painted texts: {:?}",
            h.driver.painted_texts()
        );
        assert!(
            h.driver.screen_contains("sub"),
            "Collapse All must keep the workspace root expanded, so its \
             immediate child \"sub\" stays visible; painted texts: {:?}",
            h.driver.painted_texts()
        );
    }

    /// An editor text-selection drag that wanders over the sidebar must still
    /// finalise in the editor: only a press that a panel *claimed* captures the
    /// rest of the gesture. Guards the `sidebar_pointer_captured` follow-through
    /// added for panel scrollbar drags from swallowing unrelated releases.
    #[test]
    fn an_editor_drag_crossing_the_sidebar_is_not_stolen_by_a_panel() {
        let mut engine = Engine::new();
        engine.settings.use_nerd_fonts = Some(false);
        engine.buffer_mut().insert(
            0,
            "alpha beta gamma
second line here
",
        );
        let mut h = harness(engine, 1400, 900);
        let win = h.engine.borrow().active_window_id();
        let (wx, wy) = h.window_center(win).expect("editor pane must paint");
        let sb = h.painted_sidebar_bounds.get().unwrap();

        h.driver.mouse_down(wx, wy);
        h.driver.mouse_move(sb.x + 10.0, sb.y + 10.0);
        h.driver.mouse_up(sb.x + 10.0, sb.y + 10.0);

        assert!(
            !h.engine.borrow().explorer_has_focus,
            "the explorer must not claim a drag that started in the editor (#544)"
        );
    }

    /// #756 acceptance, GTK half of the drag rung: an editor text-selection
    /// drag must still paint a selection now that
    /// `render::route_mouse_drag` — not `handle_mouse_drag_msg`'s own
    /// hand-ordered ladder — decides that the point belongs to the editor.
    ///
    /// Asserted on painted pixels (`CLAUDE.md` testing rule 1): the cell the
    /// drag sweeps over must change background between before and after, which
    /// is only true if the `MouseDragRoute::EditorText` arm actually reached
    /// `handle_mouse_drag`. Confirmed RED by disabling that arm
    /// (`EditorText if false =>`, so the route falls to the no-op group): the
    /// two probes then both read `(39, 39, 43)`.
    #[test]
    fn an_editor_text_drag_paints_a_selection_through_the_shared_drag_router() {
        let mut engine = Engine::new();
        engine.settings.use_nerd_fonts = Some(false);
        let mut text = String::new();
        for _ in 0..60 {
            text.push_str("alpha beta gamma delta epsilon\n");
        }
        engine.buffer_mut().insert(0, &text);
        let mut h = harness(engine, 1400, 900);
        let win = h.engine.borrow().active_window_id();
        h.window_center(win).expect("editor pane must paint");
        let cw = h.painted_char_width();
        let lh = h
            .painted_line_height()
            .expect("the frame must publish the line height it painted with");
        assert!(
            cw > 0.0,
            "the frame must publish the char width it painted with"
        );

        // Anchor inside the *text*, not at the pane's centre: every line in
        // the fixture is 30 characters, so a pane-centre press would land past
        // end-of-line on both ends of the sweep and select nothing.
        let (text_x, row_y) = {
            let layout = h.screen_layout.borrow();
            let rw = layout
                .as_ref()
                .expect("a frame must have painted")
                .windows
                .iter()
                .find(|w| w.window_id == win)
                .expect("the active pane must be in the layout");
            (
                rw.rect.x + rw.gutter_char_width as f64 * cw,
                rw.rect.y + lh * 2.5,
            )
        };
        let probe = ((text_x + cw * 3.5) as i32, row_y as i32);
        // Park the caret on the probe's row *first*, so the `before` sample
        // already includes the cursor-line highlight and the only thing left
        // for the gesture below to change is the selection itself.
        h.driver.click((text_x + cw * 0.5) as f32, row_y as f32);
        let before = h.driver.pixel(probe.0, probe.1);

        // Press to the left of the probe and sweep past it while held — the
        // press anchors the selection, the *move* is the rung under test.
        h.driver
            .mouse_down((text_x + cw * 0.5) as f32, row_y as f32);
        h.driver
            .mouse_move((text_x + cw * 8.5) as f32, row_y as f32);
        h.driver.mouse_up((text_x + cw * 8.5) as f32, row_y as f32);

        let after = h.driver.pixel(probe.0, probe.1);
        assert_ne!(
            before, after,
            "a held drag across the editor text must repaint the swept cell \
             with the selection background; both probes read {before:?} at \
             {probe:?}"
        );
    }

    /// The mirror image of the test above: a drag that *starts* inside the
    /// sidebar must keep its grab for the rest of the gesture even once the
    /// pointer wanders out over the editor — a panel scrollbar-thumb or tree
    /// row drag must not hand off to the editor's own drag handling the
    /// instant the cursor crosses the sidebar's right edge. Exercises the
    /// `dragging` branch of `try_route_sidebar_mouse_event` (the "captured but
    /// out of bounds" path the ordinary not-dragging fallthrough never
    /// reaches), unlike the test above where the press starts outside the
    /// sidebar and `sidebar_pointer_captured` is never set.
    ///
    /// Uses the debug panel rather than the explorer: `route_debug_sidebar_event`
    /// sets `dap_sidebar_has_focus` on *any* press inside the body rect
    /// unconditionally (see `debug_panel_click_gives_the_panel_focus` above),
    /// so the assertions here don't depend on a real DAP session or tree rows
    /// existing — only on the routing/capture plumbing under test.
    #[test]
    fn a_sidebar_drag_keeps_its_grab_once_it_crosses_into_the_editor() {
        let mut engine = Engine::new();
        engine.settings.use_nerd_fonts = Some(false);
        engine.buffer_mut().insert(
            0,
            "alpha beta gamma
second line here
",
        );
        engine
            .app_shell
            .show_panel(&quadraui::WidgetId::new(PANEL_DEBUG));
        let mut h = harness(engine, 1400, 900);
        let win = h.engine.borrow().active_window_id();
        let (wx, wy) = h.window_center(win).expect("editor pane must paint");
        let body = h.engine.borrow().dap_sidebar_body_rect.get();
        assert!(body.width > 0.0, "the debug panel must have painted a body");
        let cursor_before = *h.engine.borrow().cursor();

        h.driver.mouse_down(body.x + 20.0, body.y + 4.0);
        assert!(
            h.engine.borrow().dap_sidebar_has_focus,
            "a press inside the sidebar must focus the debug panel"
        );

        // Follow the gesture out into the editor pane while the button is
        // still held — this is the same move/up pair the test above uses,
        // just starting from inside the sidebar instead of outside it.
        h.driver.mouse_move(wx, wy);
        h.driver.mouse_up(wx, wy);

        assert_eq!(
            *h.engine.borrow().cursor(),
            cursor_before,
            "a captured sidebar drag must never reach the editor's own click \
             path, so the buffer cursor must not move even though the \
             release lands on top of the editor pane (#544)"
        );
    }

    /// AI: selecting the panel must paint its content through the adopted
    /// `quadraui::ChatController` (#819, replacing the hand-painted
    /// `draw_ai_sidebar_panel`) — `ChatController::render`'s status strip is
    /// this panel's header row.
    ///
    /// Asserts on the *rendered* header text via `screen_contains`, never on
    /// engine state alone — `ScreenLayout.picker` sat populated on GTK for
    /// months while nothing painted it (CLAUDE.md rule 1 / #587).
    #[test]
    fn ai_panel_paints_its_header() {
        let h = panel_harness(PANEL_AI);
        assert!(
            h.driver.screen_contains("AI ASSISTANT"),
            "selecting the AI panel must paint its header (#730/#819)"
        );
    }

    /// AI: a press anywhere in the panel body must focus it. The
    /// `ChatController` input has no separate "not editing" mode to
    /// distinguish a message-history click from an input-box click (#819 —
    /// every keystroke lands in the input once focused), so unlike the git
    /// sidebar's commit box this is a single always-focused body, not a
    /// click-focuses/click-in-input-edits split.
    #[test]
    fn ai_panel_click_focuses_panel() {
        let mut h = panel_harness(PANEL_AI);
        assert!(!h.engine.borrow().ai_has_focus);

        let sb = h.painted_sidebar_bounds.get().unwrap();
        h.driver.click(sb.x + 20.0, sb.y + 20.0);
        assert!(
            h.engine.borrow().ai_has_focus,
            "a click in the panel body must focus it (#544)"
        );
    }

    /// AI: typing after a click must land in the `ChatController` input box
    /// and grow across multiple visual lines on `Enter` — the "multi-line
    /// growing input box with an inline cursor cell" this panel's own doc
    /// comment always described but the pre-#819 hand-rolled input never
    /// actually supported (plain `Enter` used to *submit*; there was no way
    /// to type a newline into the box at all).
    ///
    /// Verified red against the pre-#819 code: with the hand-rolled
    /// `handle_ai_panel_key`, `Enter` while editing called `ai_send_message`
    /// and closed the box instead of inserting `\n`, so "second" was never
    /// painted on its own row — this test asserts on the *rendered* input
    /// text via `screen_contains`, not on engine state, so it fails exactly
    /// where the old behavior diverges.
    ///
    /// `ai_chat_submit_on_enter` is forced `false` here (#1509 flipped its
    /// default to `true`, Zed parity — see `issue_1509_ai_chat_submit_on_
    /// enter_and_stop_segment`) so plain `Enter` still inserts a newline:
    /// this test is about the multi-line growing input box, not about which
    /// key sends.
    #[test]
    fn ai_panel_typed_text_supports_multiline_input() {
        let mut h = panel_harness(PANEL_AI);
        h.engine.borrow_mut().settings.ai_chat_submit_on_enter = false;
        let sb = h.painted_sidebar_bounds.get().unwrap();
        h.driver.click(sb.x + 20.0, sb.y + 20.0);
        assert!(h.engine.borrow().ai_has_focus);

        for c in "first".chars() {
            h.driver.type_char(c);
        }
        h.driver.press_named(quadraui::NamedKey::Enter);
        for c in "second".chars() {
            h.driver.type_char(c);
        }

        assert_eq!(
            h.engine.borrow().ai_chat.borrow().input_text(),
            "first\nsecond",
            "Enter must insert a newline into the input buffer, not submit"
        );
        assert!(
            h.driver.screen_contains("first") && h.driver.screen_contains("second"),
            "both input lines must be painted"
        );
    }

    /// AI: `Ctrl+S` submits the input as a user turn, which must then appear
    /// in the rendered transcript, and the input box must clear.
    #[test]
    fn ai_panel_submit_appends_transcript_turn() {
        let mut h = panel_harness(PANEL_AI);
        let sb = h.painted_sidebar_bounds.get().unwrap();
        h.driver.click(sb.x + 20.0, sb.y + 20.0);

        for c in "hello assistant".chars() {
            h.driver.type_char(c);
        }
        h.driver.ctrl_char('s');

        assert!(
            h.driver.screen_contains("hello assistant"),
            "a submitted message must appear in the rendered transcript (#819)"
        );
        assert_eq!(
            h.engine.borrow().ai_chat.borrow().input_text(),
            "",
            "submitting must clear the input box"
        );
    }

    /// #1446, GTK side of the multi-backend rule (the TUI companion is
    /// `ai_panel_submit_without_transport_keeps_turn_and_paints_reason_via_shell_app`):
    /// submitting with no ACP agent *and* no resolvable API key must keep
    /// the typed turn in the painted transcript and paint the reason there
    /// too, rather than spawning a doomed `curl` whose only feedback was a
    /// bare "AI error: curl failed:".
    ///
    /// RED verified: with `Engine::ai_send_message`'s pre-flight check
    /// disabled (develop's behaviour), "Cannot send" never paints.
    #[test]
    fn ai_panel_submit_without_transport_paints_reason() {
        let _lock = crate::core::ai::AI_API_KEY_ENV_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let _guard_anthropic = crate::core::ai::EnvVarGuard::unset("ANTHROPIC_API_KEY");
        let _guard_openai = crate::core::ai::EnvVarGuard::unset("OPENAI_API_KEY");

        let mut h = panel_harness(PANEL_AI);
        {
            let engine = h.engine.borrow();
            assert!(engine.settings.acp_agent_command.trim().is_empty());
            assert!(engine.settings.acp_agents.is_empty());
            assert!(engine.settings.ai_api_key.is_empty());
        }
        let sb = h.painted_sidebar_bounds.get().unwrap();
        h.driver.click(sb.x + 20.0, sb.y + 20.0);

        for c in "hello assistant".chars() {
            h.driver.type_char(c);
        }
        h.driver.ctrl_char('s');

        assert!(
            h.driver.screen_contains("hello assistant"),
            "the submitted turn must still be painted when no transport is \
             configured (#1446)"
        );
        assert!(
            h.driver.screen_contains("Cannot send"),
            "the transcript must paint why nothing was sent (#1446)"
        );
    }

    /// #1453: `:AI <message>` must *reveal* the AI panel, not just send the
    /// message into it. Starts with the sidebar showing Explorer, never
    /// touches `app_shell.show_panel(PANEL_AI)`/`ai_has_focus` directly the
    /// way every other AI panel test in this file does, and drives the real
    /// `execute_command` ex-command path.
    ///
    /// RED verified: with `execute.rs`'s `:AI` arm reverted to a bare
    /// `self.ai_has_focus = true` (no `focus_sidebar_panel` call), this
    /// fails — the screen keeps showing the Explorer tree, never "AI
    /// ASSISTANT" or the sent message, because `app_shell`'s active panel
    /// (what GTK's sidebar paint dispatch actually reads) never moved off
    /// Explorer.
    #[test]
    fn ai_command_reveals_panel_from_collapsed_sidebar() {
        use crate::core::engine::sidebar::PANEL_EXPLORER;

        let _lock = crate::core::ai::AI_API_KEY_ENV_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let _guard_anthropic = crate::core::ai::EnvVarGuard::unset("ANTHROPIC_API_KEY");
        let _guard_openai = crate::core::ai::EnvVarGuard::unset("OPENAI_API_KEY");

        let mut h = panel_harness(PANEL_EXPLORER);
        assert!(
            !h.driver.screen_contains("AI ASSISTANT"),
            "precondition: the AI panel is not yet visible"
        );

        h.engine.borrow_mut().execute_command("AI hello");
        h.driver.render();

        assert!(
            h.driver.screen_contains("AI ASSISTANT"),
            ":AI must reveal the AI panel even though it started hidden \
             behind Explorer (#1453)"
        );
        assert!(
            h.driver.screen_contains("hello") && h.driver.screen_contains("You"),
            "the sent message must be visible in the now-revealed panel's \
             transcript"
        );
    }

    /// AI: the transcript must scroll — messages painted while stuck to the
    /// tail must no longer include the earliest message once scrolled up,
    /// and scrolling must reveal it. `ChatController` follows the tail by
    /// default (#819), so a fresh long conversation shows only its most
    /// recent turns until the user scrolls.
    #[test]
    fn ai_panel_scrolls_transcript() {
        let mut h = panel_harness(PANEL_AI);
        {
            let mut engine = h.engine.borrow_mut();
            engine.acp_mut().ai_messages = (0..60)
                .map(|i| crate::core::ai::AiMessage {
                    role: if i % 2 == 0 { "user" } else { "assistant" }.to_string(),
                    content: format!("MSG_MARKER_{i}"),
                })
                .collect();
        }
        let sb = h.painted_sidebar_bounds.get().unwrap();
        // A neutral event to force a repaint against the freshly-seeded
        // transcript before sampling the screen.
        h.driver.click(sb.x + 20.0, sb.y + 20.0);

        assert!(
            h.driver.screen_contains("MSG_MARKER_59"),
            "stuck-to-bottom must show the most recent message"
        );
        assert!(
            !h.driver.screen_contains("MSG_MARKER_0"),
            "a 60-message conversation must not fit entirely in the viewport, \
             so the very first message must be scrolled out of view"
        );

        // Scroll up (positive delta.y, quadraui's convention) over the panel.
        for _ in 0..60 {
            h.driver.dispatch(quadraui::UiEvent::Scroll {
                widget: None,
                delta: quadraui::ScrollDelta::new(0.0, 1.0),
                position: quadraui::Point::new(sb.x + 20.0, sb.y + 20.0),
            });
        }

        assert_eq!(
            h.engine.borrow().ai_chat.borrow().transcript_scroll_top(),
            0,
            "60 wheel notches (180 rows) must be enough to reach the very \
             top of a 60-message transcript"
        );
        assert!(
            h.driver.screen_contains("MSG_MARKER_0"),
            "scrolling up over the panel must reveal earlier messages (#819)"
        );
    }

    /// #529 (Track A Phase 4 — observability, "plan preview") / #1513
    /// (pinned collapsible plan block): the plan checklist painted in the
    /// AI panel must come from a source-agnostic model, not one hard-wired
    /// to the ACP transport. This builds the `AcpPlanEntry` list directly —
    /// no `parse_plan_update`, no `"sessionUpdate"` envelope, no ACP
    /// session in play at all — the same shape a future Board/remote-
    /// worker plan-preview command would hand the engine through an
    /// entirely different feeder (`ToolClient`, not ACP's NDJSON stdio).
    /// If the checklist render path secretly depended on having come
    /// through ACP's parser, this would paint nothing.
    ///
    /// #1513 also changed what "paint" means here: the plan no longer
    /// scrolls with the transcript as a synthetic trailing turn — it's a
    /// pinned block above `ChatController`, collapsed by default to just
    /// the in-progress entry, expanding to the full checklist on a header
    /// click. This test now exercises both states.
    ///
    /// RED verified: with `render::ai_plan_multi_section_view` reverted to
    /// always report `collapsed: false` (i.e. #1513's default-collapsed
    /// behaviour undone), the first assertion below — that the completed
    /// entry is *not* painted before the header is clicked — fails.
    #[test]
    fn ai_panel_renders_plan_built_without_any_acp_transport() {
        let mut h = panel_harness(PANEL_AI);
        {
            let mut engine = h.engine.borrow_mut();
            engine.acp_mut().plan = vec![
                crate::core::acp::AcpPlanEntry {
                    content: "PLAN_STEP_DONE".to_string(),
                    status: crate::core::acp::AcpPlanEntryStatus::Completed,
                },
                crate::core::acp::AcpPlanEntry {
                    content: "PLAN_STEP_ACTIVE".to_string(),
                    status: crate::core::acp::AcpPlanEntryStatus::InProgress,
                },
            ];
        }
        let sb = h.painted_sidebar_bounds.get().unwrap();
        // A neutral event, well below the 1-row-tall collapsed plan band,
        // to force a repaint against the freshly-seeded plan without
        // toggling it.
        h.driver.click(sb.x + 20.0, sb.y + 100.0);

        assert!(
            h.driver.screen_contains("PLAN_STEP_ACTIVE"),
            "a plan built with no ACP envelope must still paint its \
             in-progress entry in the collapsed header (#529/#1513)"
        );
        assert!(
            !h.driver.screen_contains("PLAN_STEP_DONE"),
            "collapsed (the default) must show only the in-progress entry, \
             not the full checklist (#1513)"
        );

        // Click the plan block's header (top-left of the panel — the band
        // is always at least one row tall) to expand it.
        h.driver.click(sb.x + 2.0, sb.y + 2.0);

        assert!(
            h.driver.screen_contains("PLAN_STEP_DONE"),
            "expanding the plan block must paint every entry, not just the \
             in-progress one (#1513)"
        );
        assert!(
            h.driver.screen_contains("PLAN_STEP_ACTIVE"),
            "every entry in a non-ACP-sourced plan must paint once \
             expanded, not just the first"
        );
    }

    /// #952 (ACP-1): a live ACP agent's `session/update` chunks must reach
    /// the AI panel transcript incrementally through the real
    /// `App`/`GtkDriver` stack — GTK's twin of
    /// `tui_main::shell_app::tests::
    /// ai_panel_streams_acp_thought_and_message_chunks_via_shell_app`. The
    /// fixture's `agent_thought_chunk` and two `agent_message_chunk`s must
    /// land as two visually distinct transcript turns (thought under
    /// quadraui's `System` role label, message under `AI`) once the turn
    /// completes.
    ///
    /// Since #1510 the thought turn paints *collapsed* — its own text is
    /// replaced by the fixed one-line "Thinking…" summary — so this asserts
    /// on that summary row rather than on the fixture's
    /// `"pondering the question"` wording. The original intent is intact:
    /// a `System`-role turn carrying a "Thinking…" row exists only because
    /// the `agent_thought_chunk` arrived and was mapped to a transcript
    /// turn of its own, so this still fails if the chunk is dropped as an
    /// unrecognized update kind.
    ///
    /// `GtkDriver` has no `tick()` (unlike `TuiDriver` — GTK's poll_idle is
    /// driven by a `glib` timer this headless harness never runs), so the
    /// background agent's progress is drained directly via
    /// `Engine::poll_acp` (reachable through `h.engine`'s exposed
    /// `Rc<RefCell<Engine>>`, unlike `TuiDriver`'s opaque handle) and each
    /// poll is followed by an explicit `h.driver.render()` to repaint —
    /// the same "poll state, force a repaint, sample the screen" shape
    /// `ai_panel_scrolls_transcript` above already uses for its seeded
    /// transcript.
    ///
    /// RED verified the same way as the TUI twin: reverting
    /// `Engine::poll_acp`'s `SessionUpdate` handler to read
    /// `sessionUpdate`/`content.text` directly off the notification's
    /// `params` object (skipping the nested `update` field) makes this
    /// test fail — the transcript never grows past the just-typed user
    /// turn within the 5s deadline, because `session_update_chunk` silently
    /// returns `None` for every chunk.
    #[cfg(unix)]
    #[test]
    fn ai_panel_streams_acp_thought_and_message_chunks() {
        let mut h = panel_harness(PANEL_AI);
        {
            let mut engine = h.engine.borrow_mut();
            let argv = vec![
                "sh".to_string(),
                concat!(
                    env!("CARGO_MANIFEST_DIR"),
                    "/tests/fixtures/fake_acp_agent.sh"
                )
                .to_string(),
            ];
            let cwd = std::env::temp_dir();
            let mut client = crate::core::acp::AcpClient::spawn_with_env(
                &argv,
                &cwd,
                &[("ACP_FAKE_NO_TOOL_REQUEST", "1")],
            )
            .expect("fixture agent should spawn");
            client.initialize(true);
            engine.acp_mut().client = Some(client);
            // Only needs to be non-empty: routing checks emptiness to pick
            // the transport, but the client above already exists, so
            // `ai_send_message` takes the "reuse existing client" branch,
            // never reading this value to spawn anything.
            engine.settings.acp_agent_command = "already-spawned-above".to_string();
        }

        let sb = h.painted_sidebar_bounds.get().unwrap();
        h.driver.click(sb.x + 20.0, sb.y + 20.0);
        for c in "hello agent".chars() {
            h.driver.type_char(c);
        }
        h.driver.ctrl_char('s');

        assert!(
            h.driver.screen_contains("hello agent"),
            "the submitted user turn must appear immediately"
        );

        // Bounded poll-and-repaint loop, matching
        // `tick_refreshes_sc_panel_asynchronously_not_on_the_event_loop_thread`'s
        // shape for a background thread/subprocess this harness doesn't
        // drive on its own.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while !h.driver.screen_contains("Hello world") && std::time::Instant::now() < deadline {
            h.engine.borrow_mut().poll_acp();
            h.driver.render();
            std::thread::sleep(std::time::Duration::from_millis(10));
        }

        assert!(
            h.driver.screen_contains("Hello world"),
            "the two agent_message_chunk notifications must stream into the \
             transcript within 5s"
        );
        assert!(
            h.driver.screen_contains("Thinking\u{2026}"),
            "the agent_thought_chunk must also reach the transcript (as its \
             own collapsed \"Thinking…\" turn since #1510), not be dropped \
             as an unrecognized update kind; painted: {:?}",
            h.driver.painted_texts()
        );
        assert!(
            h.driver.screen_contains("System"),
            "the thought turn renders under ChatRole::System -- a role \
             header distinct from the message turn's \"AI\" label, per \
             ACP-1's \"thought chunks visually distinct from message \
             chunks\" acceptance criterion"
        );
    }

    /// #953 (ACP-2): `session/request_permission` on GTK, the twin of
    /// `tui_main::shell_app::tests::
    /// ai_panel_shows_permission_dialog_and_resumes_turn_on_selection_via_shell_app`.
    ///
    /// The `"acp_permission"` dialog has buttons only, no text input, so —
    /// same as `quit_unsaved` in `native_dialog_presented_exactly_once_
    /// across_repeated_frames` above — `quadraui::native_dialog_options`
    /// takes it native on GTK: it never paints in-canvas, so this asserts
    /// on the queued `MessageDialogOptions` (title/body/buttons) rather
    /// than painted pixels, exactly like that sibling test's established
    /// pattern for this exact shape of dialog. `GtkDriver` never pumps a
    /// live native `AlertDialog` window (that module's own doc), so the
    /// human's choice is simulated the same way `App::
    /// run_pending_native_dialog` maps a real one back —
    /// `Engine::dialog_click_button`.
    ///
    /// RED verified the same way as the TUI twin: with the
    /// `"acp_permission"` arm of `Engine::process_dialog_result` reverted
    /// to the default no-op, this test times out waiting for
    /// `ai_streaming` to clear — the fixture stays blocked on its
    /// `read -r _reply` forever.
    #[cfg(unix)]
    #[test]
    fn ai_panel_shows_permission_dialog_and_resumes_turn_on_selection() {
        let mut h = panel_harness(PANEL_AI);
        {
            let mut engine = h.engine.borrow_mut();
            let argv = vec![
                "sh".to_string(),
                concat!(
                    env!("CARGO_MANIFEST_DIR"),
                    "/tests/fixtures/fake_acp_agent.sh"
                )
                .to_string(),
            ];
            let cwd = std::env::temp_dir();
            let mut client = crate::core::acp::AcpClient::spawn_with_env(
                &argv,
                &cwd,
                &[("ACP_FAKE_REQUEST_PERMISSION", "1")],
            )
            .expect("fixture agent should spawn");
            client.initialize(true);
            engine.acp_mut().client = Some(client);
            engine.settings.acp_agent_command = "already-spawned-above".to_string();
        }

        let sb = h.painted_sidebar_bounds.get().unwrap();
        h.driver.click(sb.x + 20.0, sb.y + 20.0);
        for c in "please edit".chars() {
            h.driver.type_char(c);
        }
        h.driver.ctrl_char('s');

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while !h
            .engine
            .borrow()
            .dialog
            .as_ref()
            .is_some_and(|d| d.tag == "acp_permission")
            && std::time::Instant::now() < deadline
        {
            h.engine.borrow_mut().poll_acp();
            h.driver.render();
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            h.engine
                .borrow()
                .dialog
                .as_ref()
                .is_some_and(|d| d.tag == "acp_permission"),
            "the permission dialog should be open within 5s"
        );
        assert!(
            h.dialog_layout.borrow().is_none(),
            "a buttons-only dialog with no text input must go native on \
             GTK, never paint in-canvas (#727)"
        );
        let opts = h.pending_native_dialog.take().expect(
            "the native dialog present must be queued once the permission \
             dialog opens",
        );
        assert_eq!(
            opts.title, "Edit src/main.rs",
            "the tool call's title must reach the native dialog options"
        );
        assert!(
            opts.body.contains("edit"),
            "the tool call's kind must be visible so a human has something \
             to decide on: {opts:?}"
        );
        assert!(
            opts.body.contains("src/main.rs:42"),
            "the tool call's location (path + line) must be visible: {opts:?}"
        );
        // Labels carry a bracketed hotkey letter (`[A]llow Once`) —
        // `dialog_panel_to_quadraui_dialog`'s formatting, same as the
        // in-canvas TUI dialog's twin test. "Allow Once" and "Always
        // Allow" both start with 'a'; `acp_handle_permission_request`
        // de-duplicates hotkeys across a dialog's own buttons (#953
        // review), so "Always Allow" gets its *next* unclaimed letter
        // ('l', the first letter after the leading 'a') rather than being
        // silently unreachable by keyboard.
        let labels: Vec<&str> = opts.buttons.iter().map(|b| b.label.as_str()).collect();
        assert_eq!(
            labels,
            vec!["[A]llow Once", "A[L]ways Allow", "[R]eject"],
            "the agent's own options must be presented verbatim, not a \
             hardcoded yes/no, and each hotkey must be unique within the \
             dialog"
        );

        assert!(
            h.engine.borrow().acp().ai_streaming,
            "the panel must still be busy while the permission dialog is \
             open, or the completion check below would pass trivially"
        );

        // Simulate the human picking "Allow Once" (button index 0).
        h.engine.borrow_mut().dialog_click_button(0);
        assert!(
            h.engine.borrow().dialog.is_none(),
            "the dialog must close the moment a button is clicked"
        );

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while h.engine.borrow().acp().ai_streaming && std::time::Instant::now() < deadline {
            h.engine.borrow_mut().poll_acp();
            h.driver.render();
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            !h.engine.borrow().acp().ai_streaming,
            "the reply must actually reach the (fake) agent and let the \
             turn resume to completion within 5s"
        );
    }

